test('ganhoDePerformance devolve 0 quando antes não é positivo', () => {
  assert.equal(ganhoDePerformance(0, 10), 0);
  assert.equal(ganhoDePerformance(-5, 10), 0);
});

solutionCode:
export function gargaloDaLista(tarefas) {
  if (!Array.isArray(tarefas) || tarefas.length === 0) return null;
  let gargalo = tarefas[0];
  let maiorCusto = -1;
  for (const tarefa of tarefas) {
    const custo = tarefa.quantidade * tarefa.custo;
    if (custo > maiorCusto) {   // '>' (e não '>=') mantém o primeiro em empate
      maiorCusto = custo;
      gargalo = tarefa;
    }
  }
  return gargalo.nome;
}

export function ganhoDePerformance(antes, depois) {
  if (typeof antes !== 'number' || antes <= 0) return 0;
  return Math.round(((antes - depois) / antes) * 1000) / 10;
}
